def candidate(q, k, v):
    b, h, n, d = q.shape
    block = 128
    def attend(i):
        qs = jax.lax.dynamic_slice_in_dim(q, i * block, block, axis=2)
        s = jnp.matmul(qs, jnp.swapaxes(k, -1, -2)) * jnp.float32(d ** -0.5)
        rows = i * block + jnp.arange(block)
        s = jnp.where(rows[:, None] >= jnp.arange(n)[None, :], s, -jnp.inf)
        return jnp.matmul(jax.nn.softmax(s, axis=-1), v)
    out = jax.lax.map(attend, jnp.arange(n // block))
    return out.transpose(1, 2, 0, 3, 4).reshape(q.shape)

def candidate(q, k, v):
    n, d = q.shape[-2:]
    unit = n // 16
    bounds = [0, 3 * unit, 6 * unit, 9 * unit, 12 * unit, 14 * unit, n]
    outputs = []
    for start, end in zip(bounds[:-1], bounds[1:]):
        s = jnp.matmul(q[..., start:end, :], jnp.swapaxes(k[..., :end, :], -1, -2)) * jnp.float32(d ** -0.5)
        s = jnp.where(jnp.arange(start, end)[:, None] >= jnp.arange(end)[None, :], s, -jnp.inf)
        outputs.append(jnp.matmul(jax.nn.softmax(s, axis=-1), v[..., :end, :]))
    return jnp.concatenate(outputs, axis=-2)

