def candidate(q, k, v):
    b, h, n, d = q.shape
    t = 128
    blocks = q.reshape(b, h, n // t, t, d).transpose(2, 0, 1, 3, 4)
    def body(args):
        i, qb = args
        s = jnp.einsum('bhqd,bhkd->bhqk', qb, k) * (d ** -0.5)
        mask = (i * t + jnp.arange(t))[:, None] >= jnp.arange(n)[None, :]
        p = jax.nn.softmax(jnp.where(mask, s, -jnp.inf), axis=-1)
        return jnp.einsum('bhqk,bhkd->bhqd', p, v)
    out = jax.lax.map(body, (jnp.arange(n // t), blocks))
    return out.transpose(1, 2, 0, 3, 4).reshape(q.shape)

